import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Flow } from 'flow-sdk';
import { Map, Marker } from 'pigeon-maps';

// Design System Components
const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
  className?: string;
}> = ({ icon, children, variant = 'filled', onClick, disabled, className = '' }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]} ${className}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

const FieldDisplay: React.FC<{ label: string; value: string; className?: string }> = ({ label, value, className = '' }) => (
  <div className={`border border-[#595959] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none ${className}`}>
    <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
    <div className="flex items-center">
      <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate">{value}</span>
    </div>
  </div>
);

export default function App() {
  const [sourceMedia, setSourceMedia] = useState<any>(null);
  const [locationName, setLocationName] = useState<string>('');
  const [coords, setCoords] = useState<[number, number] | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedVideo, setGeneratedVideo] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  // Global CSS Injection
  useEffect(() => {
    const id = 'geo-visualizer-styles';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; color: white; font-family: 'Google Sans Text', sans-serif; overflow: hidden; }
      @keyframes pulse { 0% { opacity: 0.6; } 50% { opacity: 1; } 100% { opacity: 0.6; } }
      .animate-pulse-slow { animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleSelectMedia = async () => {
    try {
      const media = await Flow.media.select({ filter: 'all' });
      setSourceMedia(media);
      setLocationName('');
      setCoords(null);
      setGeneratedVideo(null);
      setError(null);
    } catch (err) {
      console.error('Selection failed:', err);
    }
  };

  const geolocate = async () => {
    if (!sourceMedia) return;
    setIsAnalyzing(true);
    setError(null);
    try {
      const { text } = await Flow.generate.text(
        `Analyze this media and identify the exact location or landmark shown. Return ONLY a JSON object with keys "name" (string) and "coords" (array of [lat, lng]). If unknown, use null.`,
        {
          images: sourceMedia.type === 'image' ? [{ base64: sourceMedia.base64, mimeType: sourceMedia.mimeType }] : [],
          videos: sourceMedia.type === 'video' ? [{ base64: sourceMedia.base64, mimeType: sourceMedia.mimeType }] : [],
          systemInstruction: "You are a professional geolocation expert. You identify landmarks, cities, and landscapes with high precision."
        }
      );

      // Extract JSON from response
      const jsonMatch = text.match(/\{.*\}/s);
      if (jsonMatch) {
        const data = JSON.parse(jsonMatch[0]);
        setLocationName(data.name || 'Unknown Location');
        if (data.coords && Array.isArray(data.coords)) {
          setCoords([data.coords[0], data.coords[1]]);
        }
      } else {
        throw new Error('Could not identify location details.');
      }
    } catch (err) {
      setError('Analysis failed. Try a more distinct image.');
      console.error(err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const generateOrbit = async () => {
    if (!locationName) return;
    setIsGenerating(true);
    setError(null);
    try {
      // Using Omni Flash as the default high-speed video model
      const video = await Flow.generate.video({
        prompt: `A cinematic Google Earth style drone shot of ${locationName}. 360 degree orbit rotation around the landmark, high-altitude satellite view transition into a low drone sweep, hyper-realistic, golden hour lighting, 4k cinematic.`,
        modelDisplayName: 'Omni Flash',
        aspectRatio: '16:9',
        durationSeconds: 10
      });
      setGeneratedVideo(video);
    } catch (err) {
      setError('Generation failed. Please try again.');
      console.error(err);
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = async () => {
    if (!generatedVideo) return;
    try {
      await Flow.download({
        base64: generatedVideo.base64,
        mimeType: generatedVideo.mimeType,
        filename: `orbit_${locationName.replace(/\s+/g, '_').toLowerCase()}.mp4`
      });
    } catch (err) {
      console.error('Download failed:', err);
    }
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      {/* Left Toolbar Panel */}
      <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 shrink-0">
        <div className="flex flex-col gap-[24px] items-start w-full">

          {/* Media Input */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Source Media</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <PillButton 
                icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>} 
                variant="outline"
                onClick={handleSelectMedia}
              >
                {sourceMedia ? 'Change Selection' : 'Select Photo/Video'}
              </PillButton>
              {sourceMedia && (
                <div className="w-full aspect-video rounded-xl border border-[#595959] overflow-hidden bg-black/40 flex items-center justify-center relative group">
                  {sourceMedia.type === 'image' ? (
                    <img src={`data:${sourceMedia.mimeType};base64,${sourceMedia.base64}`} className="w-full h-full object-cover" />
                  ) : (
                    <video src={`data:${sourceMedia.mimeType};base64,${sourceMedia.base64}`} className="w-full h-full object-cover" autoPlay muted loop />
                  )}
                  <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                     <span className="text-[10px] text-white/70 uppercase tracking-widest">{sourceMedia.type}</span>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Analysis */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Location Analysis</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <PillButton 
                icon={<span className="material-symbols-outlined text-[18px]">location_on</span>} 
                variant={isAnalyzing ? 'outline' : 'filled'}
                disabled={!sourceMedia || isAnalyzing}
                onClick={geolocate}
              >
                {isAnalyzing ? 'Analyzing...' : 'Geolocate Media'}
              </PillButton>

              {locationName && (
                <FieldDisplay label="Identified Location" value={locationName} />
              )}
            </div>
          </div>

          {/* Visualization */}
          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>360 Visualization</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <PillButton 
                icon={<span className="material-symbols-outlined text-[18px]">public</span>} 
                variant={isGenerating ? 'outline' : 'solid'}
                disabled={!locationName || isGenerating}
                onClick={generateOrbit}
              >
                {isGenerating ? 'Simulating Orbit...' : 'Generate 360 Orbit'}
              </PillButton>
              <p className="text-[10px] text-white/30 px-2 leading-relaxed">
                Creates a cinematic "Google Earth" style drone orbit around the identified landmark.
              </p>
            </div>
          </div>

          {error && (
            <div className="px-3 py-2 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-[11px] w-full">
              {error}
            </div>
          )}
        </div>

        {/* Bottom Export */}
        {generatedVideo && (
          <div className="flex flex-col gap-[5px] items-start w-full pt-2 border-t border-white/5">
             <PillButton 
              variant="solid" 
              icon={<span className="material-symbols-outlined text-[18px] opacity-80">download</span>}
              onClick={handleDownload}
            >
              Export Visualization
            </PillButton>
          </div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 h-full flex flex-col relative overflow-hidden">
        {/* Background Map Component */}
        <div className="absolute inset-0 z-0">
          <Map 
            height={undefined} // fill container
            defaultCenter={[20, 0]} 
            center={coords || undefined} 
            zoom={coords ? 15 : 2}
            theme={{
              '--map-background-color': '#0e0e0e',
              '--map-tile-filter': 'invert(90%) hue-rotate(180deg) brightness(85%) contrast(110%)'
            } as any}
          >
            {coords && <Marker width={40} anchor={coords} color="#ffffff" />}
          </Map>
          <div className="absolute inset-0 pointer-events-none bg-gradient-to-t from-[#0e0e0e] via-transparent to-transparent opacity-80" />
        </div>

        {/* Center Visualizer */}
        <div className="relative z-10 flex-1 flex flex-col items-center justify-center p-8 gap-6">
          {!generatedVideo && !isGenerating && (
            <div className="max-w-md text-center flex flex-col items-center gap-4">
              <div className="w-16 h-16 rounded-full border border-white/10 flex items-center justify-center bg-white/5">
                <span className="material-symbols-outlined text-[32px] text-white/20">explore</span>
              </div>
              <div>
                <h1 className="text-xl font-medium tracking-tight text-white mb-2">GeoVisualizer</h1>
                <p className="text-sm text-white/40 leading-relaxed">
                  Select a location from your gallery or storyboard. We'll identify it and generate a cinematic 360&deg; Google Earth orbit visualization.
                </p>
              </div>
            </div>
          )}

          {isGenerating && (
            <div className="flex flex-col items-center gap-4 animate-pulse-slow">
              <div className="relative w-24 h-24">
                <div className="absolute inset-0 rounded-full border-2 border-white/10 border-t-white/60 animate-spin" />
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="material-symbols-outlined text-[32px] text-white/60">travel_explore</span>
                </div>
              </div>
              <div className="text-center">
                <p className="text-sm font-medium text-white/80">Simulating Satellite Orbit</p>
                <p className="text-[11px] text-white/40">Generating cinematic drone visualization of {locationName}...</p>
              </div>
            </div>
          )}

          {generatedVideo && !isGenerating && (
            <div className="w-full max-w-4xl aspect-video rounded-2xl overflow-hidden shadow-2xl border border-white/10 bg-black group relative">
              <video 
                src={`data:${generatedVideo.mimeType};base64,${generatedVideo.base64}`} 
                className="w-full h-full object-cover" 
                autoPlay 
                muted 
                loop 
                controls
              />
              <div className="absolute top-4 left-4 flex gap-2 pointer-events-none">
                <div className="px-2 py-1 rounded-md bg-black/60 backdrop-blur-md border border-white/10 flex items-center gap-1.5">
                  <span className="material-symbols-outlined text-[14px] text-white/80">360</span>
                  <span className="text-[10px] text-white/80 font-medium uppercase tracking-wider">360&deg; Orbit View</span>
                </div>
              </div>
              <div className="absolute bottom-4 left-4 right-4 p-4 rounded-xl bg-black/60 backdrop-blur-md border border-white/10 flex items-center justify-between opacity-0 group-hover:opacity-100 transition-opacity">
                <div className="flex flex-col">
                  <span className="text-[10px] text-white/40 uppercase tracking-widest font-bold">Location</span>
                  <span className="text-sm font-medium text-white">{locationName}</span>
                </div>
                <div className="flex items-center gap-4 text-white/40">
                  <div className="flex flex-col items-end">
                    <span className="text-[10px] uppercase tracking-widest font-bold">Model</span>
                    <span className="text-[12px]">Omni Flash</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
